declare(strict_types=1);define('ATLAS_PLATFORM_DIR',dirname(__DIR__).'/plugin/atlas-platform/');require ATLAS_PLATFORM_DIR.'src/Autoloader.php';Atlas\Platform\Autoloader::register();use Atlas\Platform\PatientResources\Domain\PatientResourcePolicy;use Atlas\Platform\PatientResources\Domain\PatientResourceVariant;use Atlas\Platform\PatientResources\Repositories\PatientResourceAccessRepository;use Atlas\Platform\PatientResources\Repositories\VariantRepository;use Atlas\Platform\PatientResources\Services\PatientResourceVariantService;
