function patient_expect(bool$c,string$m):void{if(!$c){throw new RuntimeException($m);}echo"PASS: {$m}\n";}$repo=new Variants();$policy=new PatientResourcePolicy();$service=new PatientResourceVariantService($repo,new PatientAccess(),$policy);$input=['clinic_phone'=>' 555-0100 ','clinic_address'=>'1 Main St','unknown'=>'ignored'];$first=$service->save('org-a','version-a',$input,'patient-0001',10);$retry=$service->save('org-a','version-a',$input,'patient-0001',10);patient_expect($first?->customizations===['clinic_phone'=>'555-0100','clinic_address'=>'1 Main St'],'only controlled customization fields are normalized and saved');patient_expect($retry?->replayed===true&&$repo->effects===1,'patient variant retries do not duplicate effects');patient_expect($service->save('org-b','version-a',$input,'patient-0002',10)===null,'organization B cannot customize an Organization A resource');try{$service->save('org-a','version-a',['approved_footer'=>str_repeat('x',501)],'patient-0003',10);throw new RuntimeException('oversize accepted');}catch(InvalidArgumentException){patient_expect(true,'controlled customization length limits are enforced');}patient_expect($policy->validColor('#176b72')&&!$policy->validColor('red'),'branding colors require explicit hexadecimal tokens');echo"All patient resource tests passed.\n";
